mapper.select:
SELECT c.*, cat.title as category_name, coach.coach as coach_name, coach.name as coach_position FROM course c LEFT JOIN category cat ON c.category_id = cat.id LEFT JOIN coach ON c.coach_id = coach.id
AND c.name LIKE CONCAT('%', #{name}, '%')
AND c.status = #{status}
AND c.category_id = #{categoryId}
ORDER BY c.create_time DESC
